def compute(vars):
    old = vars["v1"]
    new = vars["v2"]
    if old == 0:
        return {"value": None, "trace": {"old": old, "new": new, "output_meta": {"currency": None, "scale": "percent", "unit": "percentage"}}}
    decrease_ratio = (old - new) / old
    value = decrease_ratio * 100
    return {
        "value": value,
        "trace": {
            "old": old,
            "new": new,
            "decrease_ratio": decrease_ratio,
            "output_meta": {"currency": None, "scale": "percent", "unit": "percentage"},
        },
    }
